Below is a minimal Qt5 C++ example that:

- Presents a simple GUI to choose a directory.
- Scans that directory for .xlsx and .xls files.
- Converts each to CSV into a new subfolder named csv_export.

Notes:
- On Windows, it uses ActiveQt (QAxObject) to automate Microsoft Excel.
- On other platforms (or as a fallback on Windows), it tries to call LibreOffice (soffice) in headless mode via QProcess. Make sure LibreOffice is installed and soffice is on PATH.

main.cpp
```cpp
#include <QApplication>
#include <QWidget>
#include <QPushButton>
#include <QVBoxLayout>
#include <QHBoxLayout>
#include <QLabel>
#include <QFileDialog>
#include <QDir>
#include <QDirIterator>
#include <QMessageBox>
#include <QTextEdit>
#include <QProcess>
#include <QFileInfo>
#include <QStandardPaths>

#ifdef Q_OS_WIN
#include <QAxObject>
#endif

class MainWindow : public QWidget {
    Q_OBJECT
public:
    MainWindow(QWidget* parent = nullptr) : QWidget(parent) {
        setWindowTitle("Excel to CSV Converter (Qt5)");
        auto* layout = new QVBoxLayout(this);

        auto* pathRow = new QHBoxLayout();
        dirLabel = new QLabel("No directory selected", this);
        dirLabel->setWordWrap(true);
        auto* browseBtn = new QPushButton("Select Directory", this);
        pathRow->addWidget(dirLabel, 1);
        pathRow->addWidget(browseBtn);
        layout->addLayout(pathRow);

        convertBtn = new QPushButton("Convert to CSV", this);
        convertBtn->setEnabled(false);
        layout->addWidget(convertBtn);

        logBox = new QTextEdit(this);
        logBox->setReadOnly(true);
        layout->addWidget(logBox, 1);

        connect(browseBtn, &QPushButton::clicked, this, &MainWindow::chooseDirectory);
        connect(convertBtn, &QPushButton::clicked, this, &MainWindow::convertAll);
        resize(700, 400);
    }

private slots:
    void chooseDirectory() {
        QString dir = QFileDialog::getExistingDirectory(this, "Select directory containing Excel files");
        if (!dir.isEmpty()) {
            selectedDir = QDir::cleanPath(dir);
            dirLabel->setText(selectedDir);
            convertBtn->setEnabled(true);
            logBox->clear();
            log("Selected directory: " + selectedDir);
        }
    }

    void convertAll() {
        if (selectedDir.isEmpty()) {
            QMessageBox::warning(this, "No directory", "Please select a directory first.");
            return;
        }

        QDir base(selectedDir);
        if (!base.exists()) {
            QMessageBox::warning(this, "Invalid directory", "The selected directory does not exist.");
            return;
        }

        // Create output directory
        QString outDirPath = base.absoluteFilePath("csv_export");
        QDir outDir(outDirPath);
        if (!outDir.exists() && !QDir().mkpath(outDirPath)) {
            QMessageBox::critical(this, "Error", "Failed to create output directory: " + outDirPath);
            return;
        }
        log("Output directory: " + outDirPath);

        // Find Excel files
        QStringList nameFilters = {"*.xlsx", "*.xls"};
        QDirIterator it(selectedDir, nameFilters, QDir::Files | QDir::NoDotAndDotDot);
        QStringList files;
        while (it.hasNext()) files << it.next();

        if (files.isEmpty()) {
            log("No Excel files found.");
            QMessageBox::information(this, "Done", "No Excel files found in the selected directory.");
            return;
        }

        convertBtn->setEnabled(false);

        int success = 0, fail = 0;
        for (const QString& inPath : files) {
            QFileInfo fi(inPath);
            QString outPath = outDir.absoluteFilePath(fi.completeBaseName() + ".csv");
            log(QString("Converting: %1 -> %2").arg(fi.fileName(), QFileInfo(outPath).fileName()));

            bool ok = false;

#ifdef Q_OS_WIN
            ok = convertWithExcelCOM(inPath, outPath);
            if (!ok) {
                log("  Excel COM conversion failed or Excel not available. Trying LibreOffice...");
                ok = convertWithLibreOffice(inPath, outDirPath);
                // LibreOffice writes into outDir; ensure outPath exists after this
            }
#else
            ok = convertWithLibreOffice(inPath, outDirPath);
#endif
            if (ok && QFileInfo::exists(outPath)) {
                log("  Success");
                ++success;
            } else if (ok) {
                // LibreOffice may succeed but output path differs by locale; still treat as success if exitCode==0
                log("  Conversion reported success (verify output in folder).");
                ++success;
            } else {
                log("  Failed");
                ++fail;
            }
        }

        log(QString("Done. Succeeded: %1, Failed: %2").arg(success).arg(fail));
        QMessageBox::information(this, "Finished", QString("Conversion finished.\nSucceeded: %1\nFailed: %2").arg(success).arg(fail));
        convertBtn->setEnabled(true);
    }

private:
    QLabel* dirLabel = nullptr;
    QPushButton* convertBtn = nullptr;
    QTextEdit* logBox = nullptr;
    QString selectedDir;

    void log(const QString& msg) {
        logBox->append(msg);
    }

#ifdef Q_OS_WIN
    // Uses Microsoft Excel via COM Automation (ActiveQt). Converts only the active sheet.
    bool convertWithExcelCOM(const QString& inPath, const QString& outCsvPath) {
        try {
            QAxObject excel("Excel.Application");
            if (excel.isNull()) {
                log("  Excel COM not available.");
                return false;
            }
            excel.setProperty("Visible", false);
            QAxObject* workbooks = excel.querySubObject("Workbooks");
            if (!workbooks) return false;

            QString inWin = QDir::toNativeSeparators(inPath);
            QVariant argIn(inWin);
            QAxObject* workbook = workbooks->querySubObject("Open(const QString&)", argIn);
            if (!workbook) {
                log("  Failed to open workbook via Excel.");
                excel.dynamicCall("Quit()");
                return false;
            }

            // xlCSV = 6
            QString outWin = QDir::toNativeSeparators(outCsvPath);
            QVariant format(6);
            bool saved = workbook->dynamicCall("SaveAs(const QString&, int)", outWin, format).isValid();
            workbook->dynamicCall("Close(bool)", false);
            excel.dynamicCall("Quit()");
            return saved && QFileInfo::exists(outCsvPath);
        } catch (...) {
            log("  Exception during Excel COM conversion.");
            return false;
        }
    }
#endif

    // Uses LibreOffice/soffice headless conversion. Converts first sheet by default.
    bool convertWithLibreOffice(const QString& inPath, const QString& outDirPath) {
        QString soffice = "soffice"; // or "libreoffice" on some systems; soffice is usually a symlink.
#ifdef Q_OS_WIN
        // On Windows, try common install paths if not on PATH
        // This is a best-effort; users may need to add soffice to PATH.
        QString programFiles = qEnvironmentVariable("ProgramFiles", "C:\\Program Files");
        QString programFilesX86 = qEnvironmentVariable("ProgramFiles(x86)", "C:\\Program Files (x86)");
        QStringList candidates = {
            soffice,
            programFiles + "\\LibreOffice\\program\\soffice.exe",
            programFilesX86 + "\\LibreOffice\\program\\soffice.exe"
        };
        for (const auto& c : candidates) {
            if (QFileInfo::exists(c)) { soffice = c; break; }
        }
#endif
        QProcess proc;
        QStringList args = {
            "--headless",
            "--convert-to", "csv",
            "--outdir", QDir::toNativeSeparators(outDirPath),
            QDir::toNativeSeparators(inPath)
        };
        proc.start(soffice, args);
        bool started = proc.waitForStarted(10000);
        if (!started) {
            log("  Could not start LibreOffice (soffice).");
            return false;
        }
        bool finished = proc.waitForFinished(60000); // 60s per file
        if (!finished) {
            proc.kill();
            log("  LibreOffice timed out.");
            return false;
        }
        int code = proc.exitCode();
        if (code != 0) {
            log(QString("  LibreOffice exit code: %1, stderr: %2").arg(code).arg(QString::fromLocal8Bit(proc.readAllStandardError())));
        }
        return code == 0;
    }
};

#include "main.moc"

int main(int argc, char* argv[]) {
    QApplication app(argc, argv);
    MainWindow w;
    w.show();
    return app.exec();
}
```

Project file (.pro) snippet
- If you’re on Windows and want Excel COM support, add axcontainer. Otherwise, widgets is enough.

```
QT += widgets
win32: QT += axcontainer

CONFIG += c++11
SOURCES += main.cpp
```

Build notes
- Windows Excel COM:
  - Requires Microsoft Excel installed.
  - Only the active sheet is saved to CSV. If you need all sheets, you’d have to loop through Worksheets and SaveAs each with a sheet-specific suffix.
- LibreOffice:
  - Install LibreOffice and ensure soffice is in your system PATH, or adjust the code to point to its executable.
- CSV delimiter and encoding depend on the tool’s defaults/locale. Adjust as needed if you require specific delimiters or encodings.

